const listMatchCourtUsages = `-- name: ListMatchCourtUsages :many
SELECT id, club_id, session_id, match_id, court_id, acquired_at, released_at, acquire_operation_id, release_operation_id FROM match_court_usage WHERE match_id = $1 ORDER BY acquired_at, id
`

func (q *Queries) ListMatchCourtUsages(ctx context.Context, matchID pgtype.UUID) ([]MatchCourtUsage, error) {
	rows, err := q.db.Query(ctx, listMatchCourtUsages, matchID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []MatchCourtUsage
	for rows.Next() {
		var i MatchCourtUsage
		if err := rows.Scan(
			&i.ID,
			&i.ClubID,
			&i.SessionID,
			&i.MatchID,
			&i.CourtID,
			&i.AcquiredAt,
			&i.ReleasedAt,
			&i.AcquireOperationID,
			&i.ReleaseOperationID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

